import math

def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    pref = [0] * (n + 1)
    for i, v in enumerate(a):
        pref[i + 1] = pref[i] + v

    def cross(i: int, j: int, m: int) -> int:
        return (j - i) * (pref[m] - pref[j]) - (m - j) * (pref[j] - pref[i])

    def slope_better(l1: int, l2: int, r: int) -> bool:
        return (pref[r] - pref[l1]) * (r - l2) > (pref[r] - pref[l2]) * (r - l1)

    hull: list[int] = []
    best_l, best_r = 0, k

    for r in range(k, n + 1):
        idx = r - k
        while len(hull) >= 2 and cross(hull[-2], hull[-1], idx) <= 0:
            hull.pop()
        hull.append(idx)

        lo, hi = 0, len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if slope_better(hull[mid + 1], hull[mid], r):
                lo = mid + 1
            else:
                hi = mid
        l = hull[lo]
        if (pref[r] - pref[l]) * (best_r - best_l) > (pref[best_r] - pref[best_l]) * (r - l):
            best_l, best_r = l, r

    total = pref[best_r] - pref[best_l]
    length = best_r - best_l
    g = math.gcd(total, length)
    return [total // g, length // g]
